// i18n helpers. t() returns whatever the translator returns (vdom or string);
// tx() always returns a plain string for attributes, alerts, and confirms.
export function t(key, params) {
  try {
    if (app && app.translator && typeof app.translator.trans === 'function') {
      return app.translator.trans(key, params || {});
    }
  } catch (e) {}
  return key;
}
export function tx(key, params) {
  try {
    if (app && app.translator && typeof app.translator.trans === 'function') {
      return app.translator.trans(key, params || {}, true);
    }
  } catch (e) {}
  return key;
}
export function showError(message) {
  try {
    if (app && app.alerts && typeof app.alerts.show === 'function') {
      app.alerts.show({
        type: 'error'
      }, message);
      return;
    }
  } catch (e) {}
  try {
    alert(message);
  } catch (e) {}
}

// --- Category CRUD via the store ----------------------------------------

export function loadCategoriesList() {
  return app.store.find('linkrobins-wiki-categories', {
    sort: 'position',
    page: {
      limit: 100
    }
  });
}
export function saveCategory(category, attrs) {
  // An existing model patches itself; a null/new one creates a fresh record.
  const record = category || app.store.createRecord('linkrobins-wiki-categories');
  return record.save(attrs);
}
export function deleteCategory(category) {
  return category.delete();
}

// --- Reports -------------------------------------------------------------

/**
 * The report queue. Open ones first and newest first within that, because a
 * queue is worked from the top and a resolved report is history.
 */
export function loadReports(includeResolved) {
  return app.store.find('linkrobins-wiki-reports', {
    sort: '-createdAt',
    include: 'user,article,resolvedBy',
    page: {
      limit: 50
    }
  }).then(reports => {
    const all = reports || [];
    return includeResolved ? all : all.filter(r => !r.isResolved());
  });
}
export function resolveReport(report, resolved) {
  return report.save({
    isResolved: resolved
  });
}